effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

float hash21(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }

float camada(vec2 uv, float d, float velo) {
    vec2 g = uv * d + vec2(acTime * velo, 0.0);
    vec2 cell = floor(g);
    vec2 f = fract(g) - 0.5;
    float r = hash21(cell);
    float r2 = hash21(cell + 31.1);
    if (r < 0.9) return 0.0;
    vec2 pos = (vec2(r, r2) - 0.5) * 0.4;
    float dist = length(f - pos);
    return smoothstep(0.18, 0.0, dist) * (0.5 + r2 * 0.5);
}

void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    float n = 0.0;
    n += camada(acScreenNorm, density * 0.5, speed * 0.4) * 0.6;
    n += camada(acScreenNorm, density,       speed)       * 1.0;
    n += camada(acScreenNorm, density * 1.8, speed * 1.8) * 0.4;
    float l = dot(orig.rgb, LUMA);
    float peso = onDark ? (1.0 - smoothstep(0.2, 0.6, l)) : 1.0;
    fragColor = vec4(orig.rgb + vec3(n * intensity * peso), orig.a);
}
